import{_ as d,o as n,c as e,a2 as o}from"./chunks/framework.DQSKbrc3.js";const l=JSON.parse('{"title":"Sounds: what to find / Âm thanh cần kiếm","description":"","frontmatter":{},"headers":[],"relativePath":"gdd/sounds.md","filePath":"gdd/sounds.md"}'),a={name:"gdd/sounds.md"};function c(r,t,h,i,s,m){return n(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="sounds-what-to-find-am-thanh-can-kiem" tabindex="-1">Sounds: what to find / Âm thanh cần kiếm <a class="header-anchor" href="#sounds-what-to-find-am-thanh-can-kiem" aria-label="Permalink to &quot;Sounds: what to find / Âm thanh cần kiếm&quot;">​</a></h1><p><strong>Bạn chỉ cần làm theo bảng này. / You only need this table.</strong> Mỗi dòng là một âm thanh cần kiếm. Lưu file <code>.m4a</code> đặt tên theo cột &quot;File name&quot; rồi gửi tôi, tôi sẽ gắn vào game. Pri: <strong>A</strong> = làm trước (nghe nhiều nhất), <strong>B</strong> = làm sau, <strong>C</strong> = tuỳ chọn.</p><table tabindex="0"><thead><tr><th>#</th><th>Pri</th><th>Tiếng Việt</th><th>English</th><th>File name</th><th>Khi nào phát</th></tr></thead><tbody><tr><td>1</td><td>A</td><td>Chữ combo Nice / Great / Super / Wow</td><td>Combo words</td><td><code>sfx_combo_word.m4a</code></td><td>Bấm đúng cá liên tiếp</td></tr><tr><td>1b</td><td>A</td><td>Nốt tăng dần mỗi cá vào bể trong chain (một nốt ngắn, có cao độ rõ: giọt nước, marimba, bong bóng; khoảng 0,2-0,3 giây, nốt C5)</td><td>Combo step note: tonal, short; I pitch it up the major scale</td><td><code>sfx_combo_step.m4a</code></td><td>Mỗi cá vào bể đích trong chain</td></tr><tr><td>2</td><td>A</td><td>Nắp ống mở</td><td>Pipe lid opens</td><td><code>sfx_pipe_open.m4a</code></td><td>Ống sắp thả cá</td></tr><tr><td>3</td><td>A</td><td>Nắp ống đóng</td><td>Pipe lid closes</td><td><code>sfx_pipe_close.m4a</code></td><td>Sau khi cá ra hết</td></tr><tr><td>4</td><td>A</td><td>Nước bắn</td><td>Water splash</td><td><code>sfx_splash.m4a</code></td><td>Cá nhảy ra khỏi mặt nước (bay lên bể đích, màn thắng), thả đá, thả ngọc trai, thả mồi, nước tràn lúc thua. Cá rơi xuống bể từ Backup dùng <code>sfx_fish_to_tank</code>; cá vào bể đích nhỏ và bể đích xong không còn tiếng splash</td></tr><tr><td>5</td><td>A</td><td>Bấm vào nước, cá tản ra</td><td>Tap on water, fish scatter</td><td><code>sfx_tap_water.m4a</code></td><td>Bấm chỗ trống; ống bắt đầu rung</td></tr><tr><td>6</td><td>A</td><td>Bấm trúng vật cản</td><td>Wrong / bad hit</td><td><code>sfx_bad.m4a</code></td><td>Chạm vật cản; nước tràn lúc thua</td></tr><tr><td>7</td><td>A</td><td>Bấm vào con sò</td><td>Clam tapped</td><td><code>sfx_clam_tap.m4a</code></td><td>Mỗi lần bấm (đang dùng click nút)</td></tr><tr><td>8</td><td>A</td><td>Sò đớp cá</td><td>Clam snaps shut</td><td><code>sfx_clam_snap.m4a</code></td><td>Cá cần tìm bơi gần sò</td></tr><tr><td>9</td><td>A</td><td>Sò mở ra thả cá</td><td>Clam freed</td><td><code>sfx_clam_open.m4a</code></td><td>Bấm đủ số lần</td></tr><tr><td>10</td><td>B</td><td>Hang bầy cá hiện ra</td><td>Swarm cave pops up</td><td><code>sfx_swarm_cave.m4a</code></td><td>Bắt đầu sự kiện bầy cá</td></tr><tr><td>11</td><td>B</td><td>Bầy cá bơi qua</td><td>Swarm passes</td><td><code>sfx_swarm_pass.m4a</code></td><td>Trong lúc bầy chạy (nhẹ)</td></tr><tr><td>12</td><td>B</td><td>Hai cá đánh nhau</td><td>Squabble clash</td><td><code>sfx_squabble.m4a</code></td><td>Sự kiện đánh nhau</td></tr><tr><td>13</td><td>B</td><td>Cá xếp hàng conga / khiêu vũ</td><td>Conga / waltz</td><td><code>sfx_conga_waltz.m4a</code></td><td>Hai sự kiện đó</td></tr><tr><td>14</td><td>B</td><td>Ngọc trai bị húc</td><td>Pearl bounce</td><td><code>sfx_pearl_bounce.m4a</code></td><td>Sự kiện ngọc trai</td></tr><tr><td>15</td><td>B</td><td>Cá chui vào nhà</td><td>Fish hide</td><td><code>sfx_hide.m4a</code></td><td>Sự kiện trốn</td></tr><tr><td>16</td><td>B</td><td>Tay thả mồi</td><td>Feeding hand and pellets</td><td><code>sfx_feed.m4a</code></td><td>Sự kiện cho ăn</td></tr><tr><td>17</td><td>B</td><td>Nhím / sứa bị bấm</td><td>Urchin / jelly tapped</td><td><code>sfx_obstacle_tap.m4a</code></td><td>Vật cản chạy vào Backup</td></tr><tr><td>18</td><td>B</td><td>Bắt được cá thưởng</td><td>Bounty fish caught</td><td><code>sfx_bounty.m4a</code></td><td>Cá bounty</td></tr><tr><td>19</td><td>B</td><td>Chữ LEVEL N / chữ khen hiện ra</td><td>Title / cheer pop</td><td><code>sfx_title_pop.m4a</code></td><td>Đầu level (đang là tiếng code)</td></tr><tr><td>20</td><td>B</td><td>Bóng bay vào thanh tiến độ</td><td>Gauge fill</td><td><code>sfx_gauge.m4a</code></td><td>Tank xong (đang là tiếng code)</td></tr><tr><td>21</td><td>B</td><td>Hoàn thành bước hướng dẫn</td><td>Tutorial step done</td><td><code>sfx_tutorial_ok.m4a</code></td><td>Xoay, zoom, nghiêng lần đầu (đang là tiếng code)</td></tr><tr><td>22</td><td>C</td><td>Banner hoàn thành / sao điểm</td><td>Result banner, stars</td><td><code>sfx_result.m4a</code></td><td>Màn kết quả</td></tr><tr><td>23</td><td>C</td><td>Xoay, zoom bể</td><td>Camera swish</td><td><code>sfx_camera.m4a</code></td><td>Lúc kéo (rất nhỏ)</td></tr><tr><td>24</td><td>C</td><td>Đổi hình bể</td><td>Tank shape change</td><td><code>sfx_shape_change.m4a</code></td><td>Mỗi 10 level</td></tr><tr><td>25</td><td>C</td><td>Nền nước, bong bóng</td><td>Water ambience loop</td><td><code>sfx_ambience.m4a</code></td><td>Dưới nhạc nền (rất nhỏ)</td></tr></tbody></table><p><strong>Đã chốt, không cần kiếm:</strong> chạm booster khoá dùng <code>ui_button_click</code>; Clear Tank, Clear Backup và bộ đếm combo x3/x4 không cần; cá chui ra từ ống dùng <code>sfx_fish_spawn</code>; mở/đóng Pause, Levels, Play On đã có tiếng.</p><p><strong>Đã gắn xong (đã kiểm tra khi chạy):</strong> chạm ô booster khoá phát <code>ui_button_click</code> (không dùng được booster); pop-up New Feature và pop-up hướng dẫn booster mở phát <code>popopen</code>, đóng phát <code>popclose</code>.</p><hr><h1 id="reference-cho-toi-tra-cuu-ban-khong-can-đoc-inventory" tabindex="-1">Reference (cho tôi tra cứu, bạn không cần đọc) / Inventory <a class="header-anchor" href="#reference-cho-toi-tra-cuu-ban-khong-can-đoc-inventory" aria-label="Permalink to &quot;Reference (cho tôi tra cứu, bạn không cần đọc) / Inventory&quot;">​</a></h1><h2 id="đa-co-file-ghi-am-public-sfx" tabindex="-1">Đã có file ghi âm (public/sfx) <a class="header-anchor" href="#đa-co-file-ghi-am-public-sfx" aria-label="Permalink to &quot;Đã có file ghi âm (public/sfx)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Phát khi</th></tr></thead><tbody><tr><td>bgm_ap.m4a</td><td>Nhạc nền; chạy lại mỗi level, nhỏ đi khi có pop-up</td></tr><tr><td>ui_button_click.m4a</td><td>Mọi nút; cũng dùng cho bấm vào chỗ trống (miss)</td></tr><tr><td>sfx_fish_tap.m4a</td><td>Bấm đúng cá</td></tr><tr><td>sfx_fish_to_backup.m4a</td><td>Cá vào Backup</td></tr><tr><td>sfx_fish_to_tank_or_vice_versa.m4a</td><td>Cá vào bể đích / rút từ Backup; chữ khen hiện lúc cá vào bể. File này là tiếng vù/nước nên không đổi cao độ được (đã thử, không nghe ra; nốt chuông bằng code nghe dở nên bỏ)</td></tr><tr><td>sfx_fish_spawn.m4a</td><td>Ống đẩy cá ra</td></tr><tr><td>sfx_hint.m4a</td><td>Booster gợi ý</td></tr><tr><td>sfx_level_start.m4a</td><td>Bắt đầu level</td></tr><tr><td>sfx_squid.m4a</td><td>Mực phun mực</td></tr><tr><td>sfx_tank_complete.m4a</td><td>Hoàn thành một bể đích</td></tr><tr><td>sfx_win.m4a / sfx_lose.m4a</td><td>Thắng / thua (Out of Space! = thua)</td></tr><tr><td>sfx_backup_break.m4a</td><td>Kính Backup vỡ (thua)</td></tr><tr><td>sfx_popup_open.m4a / sfx_popup_close.m4a</td><td>Mở (Pause, Levels, Intro) / đóng pop-up; rèm màn thắng</td></tr><tr><td>sfx_play_on.m4a</td><td>Mở pop-up Play On</td></tr></tbody></table><h2 id="đang-la-tieng-tong-hop-bang-code" tabindex="-1">Đang là tiếng tổng hợp bằng code <a class="header-anchor" href="#đang-la-tieng-tong-hop-bang-code" aria-label="Permalink to &quot;Đang là tiếng tổng hợp bằng code&quot;">​</a></h2><p><code>scatter</code>, <code>splash</code>, <code>land</code>, <code>complete</code>, <code>good</code>, <code>bad</code>. Có định nghĩa nhưng không bao giờ phát: <code>junk</code>, <code>plip</code>, <code>start</code> (lệnh gọi nằm trong comment), <code>ambient()</code> (tắt).</p>',11)])])}const p=d(a,[["render",c]]);export{l as __pageData,p as default};
